
"use strict";
const topics=[
["units","Units & Conversions","Conversions, exchange rates and unit rates"],
["percent","Percentages","Discounts, inflation and markups"],
["budget","Budgeting & Graphs","Expense categories and pie charts"],
["interest","Interest & Investments","Simple and compound growth"],
["loans","Loans & Amortization","Payments and repayment schedules"],
["mortgage","Student Loans & Mortgages","Deferred interest and housing"]
];
const $=s=>document.querySelector(s);
const rnd=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
const pick=a=>a[rnd(0,a.length-1)];
const money=n=>Number(n).toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:2});
const num=n=>Number(n).toLocaleString("en-US",{maximumFractionDigits:3});
const close=(a,b,decimals=2)=>Number.isFinite(a)&&Math.abs(a-Number(b.toFixed(decimals)))<=Math.pow(10,-decimals)/2+1e-8;
const payment=(P,annual,months)=>{let r=annual/1200;return r===0?P/months:P*r/(1-Math.pow(1+r,-months));};
const annuity=(d,annual,months)=>{let r=annual/1200;return r===0?d*months:d*(Math.pow(1+r,months)-1)/r;};

// Render dynamic TeX after a question, hint, solution, or exam is inserted.
function typesetMath(root=document.body){
 if(!window.MathJax?.typesetPromise)return;
 if(window.MathJax.typesetClear)window.MathJax.typesetClear([root]);
 window.MathJax.typesetPromise([root]).catch(err=>console.warn('Math rendering:',err));
}
const mathFormulas = {"Fahrenheit to Celsius": "C=\\frac59(F-32)", "Celsius to Fahrenheit": "F=\\frac95C+32", "Temperature changes and comparisons": "\\Delta F=\\frac95\\Delta C", "Weight conversion": "\\text{converted amount}=\\text{original amount}\\times\\text{conversion factor}", "Multi-step conversion": "\\text{converted amount}=\\text{original amount}\\times\\text{conversion factor}", "Unit rates": "\\text{unit price}=\\frac{\\text{total price}}{\\text{quantity}}", "Speed conversion": "\\frac{\\mathrm{ft}}{\\mathrm{s}}=\\frac{\\mathrm{mi}}{\\mathrm{h}}\\times\\frac{5280}{3600}", "Area conversion": "1\\ \\mathrm{yd}^2=9\\ \\mathrm{ft}^2", "Discount and sales tax": "\\text{final}=P\\left(1-\\frac{d}{100}\\right)\\left(1+\\frac{t}{100}\\right)", "Successive percentage increases": "\\text{final}=P\\left(1+\\frac{a}{100}\\right)\\left(1+\\frac{b}{100}\\right)", "Reverse percentages": "\\text{original}=\\frac{\\text{sale price}}{1-d/100}", "Percent change": "\\%\\text{ change}=\\frac{\\text{new}-\\text{old}}{\\text{old}}\\times100", "Markup versus profit margin": "\\text{margin}=\\frac{\\text{selling price}-\\text{cost}}{\\text{selling price}}\\times100\\%", "Monthly budget categories": "\\text{savings}=\\text{income}-\\text{expenses}", "Build a pie chart": "\\text{sector percent}=\\frac{\\text{category}}{\\text{total}}\\times100\\%", "Budget surplus or deficit": "\\text{surplus}=\\text{income}-\\text{expenses}", "Monthly savings target": "\\text{monthly saving}=\\frac{\\text{goal}-\\text{saved}}{\\text{months}}", "Simple-interest investment": "I=Prt,\\qquad A=P+I", "Compound interest": "A=P\\left(1+\\frac{r}{n}\\right)^{nt}", "Retirement contributions": "FV=D\\frac{(1+i)^N-1}{i}", "Simple versus compound": "A_{\\mathrm{simple}}=P(1+rt),\\quad A_{\\mathrm{compound}}=P(1+r/n)^{nt}", "Time to reach a goal": "t=\\frac{\\ln(A/P)}{n\\ln(1+r/n)}", "Simple-interest installment financing": "A=P(1+rt),\\qquad M=\\frac{A}{12t}", "Amortized loan payment": "M=\\frac{Pi}{1-(1+i)^{-N}}", "Credit-card repayment schedule": "I=Bi,\\quad\\text{principal paid}=M-I", "Two rows of amortization": "I_k=B_{k-1}i,\\quad B_k=B_{k-1}+I_k-M", "Financing with down payment": "P=\\text{price}-\\text{down payment}", "Deferred student loan": "I=Prt,\\qquad M=\\frac{Bi}{1-(1+i)^{-N}}", "Mortgage and down payment": "P=\\text{price}(1-d),\\quad M=\\frac{Pi}{1-(1+i)^{-N}}", "Interest paid during school": "I=Prt,\\quad M=\\frac{Pi}{1-(1+i)^{-N}}", "15-year versus 30-year mortgage": "M=\\frac{Pi}{1-(1+i)^{-N}}"};
function formulaBlock(title){
 const latex=mathFormulas[title];
 return latex ? '<div class="math-method">\\['+latex+'\\]</div>' : '';
}

const questions={
units:[
{title:"Fahrenheit to Celsius",make(){let c=pick(["A weather station records", "An outdoor thermometer shows", "A kitchen thermometer reads"]);let f=rnd(-10,110),v=(f-32)*5/9;return {text:`${c} ${f}°F. Convert this temperature to degrees Celsius. Round to one decimal place.`,fields:["Temperature (°C)"],answers:[v],decimals:[1],hint:"Subtract 32 from the Fahrenheit reading, then multiply by 5/9.",solution:`C = (${f} − 32) × 5/9 = ${v.toFixed(1)}°C.`};}},
{title:"Celsius to Fahrenheit",make(){let c=pick(["A weather forecast predicts", "A laboratory thermometer reads", "An oven temperature is"]);let v=rnd(-25,85),f=v*9/5+32;return {text:`${c} ${v}°C. Convert this temperature to degrees Fahrenheit. Round to one decimal place.`,fields:["Temperature (°F)"],answers:[f],decimals:[1],hint:"Multiply Celsius by 9/5, then add 32.",solution:`F = (${v} × 9/5) + 32 = ${f.toFixed(1)}°F.`};}},
{title:"Temperature changes and comparisons",make(){let scenario=pick(["The temperature outside rises", "A refrigerator's temperature increases", "A city's afternoon temperature climbs"]);let c1=rnd(-20,20),delta=rnd(4,25),c2=c1+delta;return {text:`${scenario} from ${c1}°C to ${c2}°C. What is the temperature increase in degrees Fahrenheit? (This is a temperature <em>change</em>, not an absolute temperature.) Round to one decimal place.`,fields:["Increase (°F)"],answers:[delta*9/5],decimals:[1],hint:"For temperature differences, multiply the Celsius change by 9/5. Do not add 32.",solution:`Change = ${c2} − (${c1}) = ${delta}°C. Fahrenheit change = ${delta} × 9/5 = ${(delta*9/5).toFixed(1)}°F.`};}},
{title:"Weight conversion",make(){let c=pick([{thing:"a shipment of flour",u:"pounds",v:"kilograms",f:.45359237},{thing:"a rescued animal",u:"kilograms",v:"pounds",f:2.2046226218},{thing:"a bag of soil",u:"pounds",v:"ounces",f:16}]);let x=rnd(20,150);return {text:`${c.thing[0].toUpperCase()+c.thing.slice(1)} weighs ${x} ${c.u}. Convert its weight to ${c.v}. Round to two decimal places.`,fields:["Converted weight"],answers:[x*c.f],tol:.015,hint:`Use the conversion factor: 1 ${c.u} = ${num(c.f)} ${c.v}.`,solution:`${x} × ${num(c.f)} = ${num(x*c.f)} ${c.v}.`};}},
{title:"Multi-step conversion",make(){let c=pick([{name:"A delivery van",start:"miles",target:"feet",factor:5280},{name:"A hiking trail",start:"kilometers",target:"meters",factor:1000},{name:"A water tank",start:"gallons",target:"quarts",factor:4}]);let x=rnd(3,24);return {text:`${c.name} has a measurement of ${x} ${c.start}. Express it in ${c.target}.`,fields:[`Number of ${c.target}`],answers:[x*c.factor],hint:`Multiply by ${c.factor} ${c.target} per ${c.start}.`,solution:`${x} × ${c.factor} = ${num(x*c.factor)} ${c.target}.`};}},
{title:"Unit rates",make(){let c=pick([{item:"apples",unit:"pounds",cost:1.7},{item:"fabric",unit:"yards",cost:3.4},{item:"fuel",unit:"gallons",cost:2.8}]);let q=rnd(4,15),p=Math.round(q*c.cost*100)/100;return {text:`A customer pays ${money(p)} for ${q} ${c.unit} of ${c.item}. What is the price per ${c.unit}?`,fields:["Unit price ($)"],answers:[p/q],tol:.015,hint:"Divide the total price by the quantity.",solution:`${money(p)} ÷ ${q} = ${money(p/q)} per ${c.unit}.`};}},
{title:"Speed conversion",make(){let mph=rnd(25,75);return {text:`A delivery vehicle travels at ${mph} miles per hour. Convert this speed to feet per second. Round to two decimal places.`,fields:["Speed (feet per second)"],answers:[mph*5280/3600],hint:"Multiply miles by 5280 feet and divide hours by 3600 seconds.",solution:`${mph} × 5280 ÷ 3600 = ${(mph*5280/3600).toFixed(2)} feet per second.`};}},
{title:"Currency exchange: dollars to foreign currency",make(){
 const c=pick([{name:"euros",symbol:"€",code:"EUR",rate:0.92},{name:"Canadian dollars",symbol:"C$",code:"CAD",rate:1.37},{name:"Mexican pesos",symbol:"MX$",code:"MXN",rate:17.85},{name:"British pounds",symbol:"£",code:"GBP",rate:0.79}]);
 const amount=rnd(12,90)*10, rate=Number((c.rate*(rnd(94,106)/100)).toFixed(4)),converted=amount*rate;
 return {text:`A traveler exchanges $${amount} US dollars. The posted rate is 1 USD = ${rate} ${c.code}. How many ${c.name} will the traveler receive? Ignore transaction fees and round to two decimals.`,fields:[`Amount (${c.code})`],answers:[converted],hint:`Multiply the number of US dollars by ${rate} ${c.code} per USD.`,authoredSolution:`<p>The rate tells us how many ${c.name} correspond to each US dollar. Multiplying by the rate cancels the USD units and leaves ${c.code}.</p><div class="math-method">\[${amount}\,\cancel{\mathrm{USD}}\times\frac{${rate}\,\mathrm{${c.code}}}{1\,\cancel{\mathrm{USD}}}=${converted.toFixed(2)}\,\mathrm{${c.code}}\]</div><p>The traveler receives <strong>${converted.toFixed(2)} ${c.code}</strong>, before fees.</p>`};
}},
{title:"Currency exchange: foreign currency to dollars",make(){
 const c=pick([{name:"euros",code:"EUR",rate:0.92},{name:"Canadian dollars",code:"CAD",rate:1.37},{name:"Mexican pesos",code:"MXN",rate:17.85},{name:"British pounds",code:"GBP",rate:0.79}]);
 const rate=Number((c.rate*(rnd(94,106)/100)).toFixed(4)),amount=rnd(15,90)*10,usd=amount/rate;
 return {text:`A store lists an item for ${amount} ${c.code}. The exchange rate is 1 USD = ${rate} ${c.code}. What is the equivalent price in US dollars? Ignore fees and round to two decimals.`,fields:["Equivalent price (USD)"],answers:[usd],hint:`Since one US dollar buys ${rate} ${c.code}, divide ${amount} by ${rate}.`,authoredSolution:`<p>Here the exchange rate is expressed as foreign currency per US dollar. To find the dollar price, we divide the foreign-currency amount by that rate, rather than multiplying.</p><div class="math-method">\[${amount}\,\cancel{\mathrm{${c.code}}}\times\frac{1\,\mathrm{USD}}{${rate}\,\cancel{\mathrm{${c.code}}}}\approx ${usd.toFixed(2)}\,\mathrm{USD}\]</div><p>The equivalent price is <strong>$${usd.toFixed(2)}</strong>.</p>`};
}},
{title:"Currency exchange: compare two prices",make(){
 const c=pick([{code:"EUR",rate:0.92},{code:"CAD",rate:1.37},{code:"GBP",rate:0.79}]);
 const rate=Number((c.rate*(rnd(94,106)/100)).toFixed(4)),us=rnd(40,120)*5,foreign=Math.round(us*rate*(rnd(85,115)/100)),converted=foreign/rate,difference=Math.abs(us-converted);
 return {text:`A jacket costs $${us} in a US shop or ${foreign} ${c.code} in an overseas shop. The exchange rate is 1 USD = ${rate} ${c.code}. Ignoring shipping, tax and fees, what is the overseas price in USD, and how much cheaper is the less expensive option? Round both answers to two decimals.`,fields:["Overseas price (USD)","Savings choosing the cheaper option (USD)"],answers:[converted,difference],hint:`Convert ${foreign} ${c.code} into USD by dividing by ${rate}, then subtract the smaller dollar price from the larger.`,authoredSolution:`<p>To compare prices fairly, both must be expressed in the same currency. The overseas price in US dollars is ${foreign} divided by ${rate}.</p><div class="math-method">\[\frac{${foreign}\,\mathrm{${c.code}}}{${rate}\,\mathrm{${c.code}/USD}}\approx\$${converted.toFixed(2)}\]</div><p>The US shop charges $${us.toFixed(2)}, while the overseas shop charges approximately $${converted.toFixed(2)}. The ${converted<us?'overseas':'US'} shop is cheaper, and the difference is <strong>$${difference.toFixed(2)}</strong>.</p>`};
}},
{title:"Area conversion",make(){let feet=rnd(3,25)*9;return {text:`A rectangular garden covers ${feet} square feet. How many square yards is this?`,fields:["Area (square yards)"],answers:[feet/9],hint:"One square yard contains 9 square feet.",solution:`${feet} ÷ 9 = ${feet/9} square yards.`};}}
],
percent:[
{title:"Discount and sales tax",make(){let c=pick(["A laptop backpack","A desk chair","A bicycle helmet"]);let p=rnd(8,40)*10,d=pick([10,15,20,25,30]),tax=pick([5,6,7,8]);let discounted=p*(1-d/100),total=discounted*(1+tax/100);return {text:`${c} is priced at ${money(p)}. It is discounted by ${d}%, then ${tax}% sales tax is charged on the discounted price. Find the final price.`,fields:["Final price ($)"],answers:[total],tol:.015,hint:"Apply the discount first, then multiply by the tax factor.",solution:`${money(p)} × (1−${d}/100) × (1+${tax}/100) = ${money(total)}.`};}},
{title:"Successive percentage increases",make(){let c=pick(["A manufactured product passes through two suppliers","A delivery service adds two successive operating surcharges","A food distributor adjusts its costs twice"]);let p=rnd(5,35)*20,a=rnd(3,12),b=rnd(4,15);let final=p*(1+a/100)*(1+b/100),pct=(final/p-1)*100;return {text:`${c}. The starting cost is ${money(p)}. The cost increases ${a}%, then increases another ${b}% on the new amount. Find the final cost and overall percentage increase.`,fields:["Final cost ($)","Overall increase (%)"],answers:[final,pct],tol:.02,hint:"Multiply successive growth factors; do not simply add the percentages.",solution:`Final cost = ${money(p)}(1+${a}/100)(1+${b}/100) = ${money(final)}. Overall increase = ${num(pct)}%.`};}},
{title:"Reverse percentages",make(){let c=pick(["A restaurant meal","A jacket","A concert ticket"]);let original=rnd(12,90)*5,discount=pick([10,20,25,30]);let sale=original*(1-discount/100);return {text:`After a ${discount}% discount, ${c.toLowerCase()} costs ${money(sale)}. What was its original price?`,fields:["Original price ($)"],answers:[original],hint:"Divide the sale price by the fraction of the original price that remains.",solution:`${money(sale)} ÷ (1−${discount}/100) = ${money(original)}.`};}},
{title:"Percent change",make(){let old=rnd(20,80)*20,change=rnd(-15,20),now=old*(1+change/100);return {text:`Attendance at a festival changes from ${old} to ${num(now)} visitors. Find the signed percentage change (negative for a decrease).`,fields:["Percent change (%)"],answers:[change],hint:"(New − original) ÷ original × 100.",solution:`(${num(now)} − ${old}) ÷ ${old} × 100 = ${change}%.`};}},
{title:"Markup versus profit margin",make(){let cost=rnd(12,50)*5,markup=pick([20,25,30,40]),sale=cost*(1+markup/100);return {text:`A retailer purchases an item for ${money(cost)} and marks it up ${markup}% based on cost. Find the selling price and profit margin as a percentage of selling price.`,fields:["Selling price ($)","Profit margin (%)"],answers:[sale,100*(sale-cost)/sale],hint:"Markup uses cost as denominator; profit margin uses selling price.",solution:`Price = ${money(sale)}; margin = (${money(sale)} − ${money(cost)}) ÷ ${money(sale)} × 100 = ${(100*(sale-cost)/sale).toFixed(2)}%.`};}}
],
budget:[
{title:"Monthly budget categories",make(){let salary=rnd(25,45)*100;let vals=[rnd(7,11)*100,rnd(2,4)*100,rnd(3,5)*100,rnd(2,4)*100];let sum=vals.reduce((a,b)=>a+b,0),save=salary-sum;return {text:`A household earns ${money(salary)} monthly. Housing: ${money(vals[0])}; transportation: ${money(vals[1])}; food: ${money(vals[2])}; other expenses: ${money(vals[3])}. Determine savings and the percentage of income spent on housing.`,fields:["Monthly savings ($)","Housing (% of income)"],answers:[save,100*vals[0]/salary],tol:.02,hint:"Savings = income − total expenses. Housing percentage = housing ÷ income × 100.",solution:`Savings = ${money(salary)} − ${money(sum)} = ${money(save)}. Housing = ${num(100*vals[0]/salary)}%.`};}},
{title:"Build a pie chart",pie:true,make(){let c=pick(["a student's monthly spending","a community club's budget","a family's monthly expenses"]);let parts=[rnd(25,45),rnd(12,25),rnd(10,22),rnd(5,15)];let sum=parts.reduce((a,b)=>a+b,0);parts.push(100-sum);if(parts[4]<0)return this.make();return {text:`Create a pie chart for ${c}. Target percentages: Housing ${parts[0]}%, Transport ${parts[1]}%, Food ${parts[2]}%, Other ${parts[3]}%, Savings ${parts[4]}%. Adjust each sector using the sliders. The last sector automatically fills the remaining percentage.`,pieParts:parts,fields:[],answers:[],hint:"Set the first four sectors to their target percentages. The fifth sector is the remainder to 100%.",solution:`The five sector percentages are ${parts.join("%, ")}%. Their sum is 100%.`};}},
{title:"Budget surplus or deficit",make(){let income=rnd(18,30)*100,expenses=[rnd(8,14)*100,rnd(3,6)*100,rnd(2,5)*100],total=expenses.reduce((a,b)=>a+b,0);return {text:`A household earns ${money(income)} each month and spends ${expenses.map(money).join(", ")} on three expense categories. Find the signed monthly surplus (negative if a deficit) and the percent of income spent.`,fields:["Surplus or deficit ($)","Percent spent (%)"],answers:[income-total,100*total/income],hint:"Subtract total expenses from income; divide expenses by income.",solution:`Expenses = ${money(total)}; surplus = ${money(income-total)}; percent spent = ${(100*total/income).toFixed(2)}%.`};}},
{title:"Monthly savings target",make(){let goal=rnd(15,45)*100,saved=rnd(3,12)*100,months=pick([4,5,6,8,10]);return {text:`A student wants to save ${money(goal)} for a computer and already has ${money(saved)}. With no interest, how much must be saved per month for the next ${months} months?`,fields:["Monthly savings ($)"],answers:[(goal-saved)/months],hint:"(Goal − already saved) ÷ months.",solution:`(${money(goal)} − ${money(saved)}) ÷ ${months} = ${money((goal-saved)/months)}.`};}}
],
interest:[
{title:"Simple-interest investment",make(){let c=pick(["A certificate of deposit","A short-term business reserve","A family savings investment"]);let P=rnd(30,150)*100,r=pick([2.5,3,3.5,4,4.5,5]),months=pick([6,12,18,24,30,36]);let I=P*r/100*months/12;return {text:`${c} starts with ${money(P)} and earns ${r}% annual simple interest for ${months} months. Find the interest and final amount.`,fields:["Interest earned ($)","Final amount ($)"],answers:[I,P+I],tol:.015,hint:"Use I = Prt, with time expressed in years.",solution:`I = ${money(P)} × ${r/100} × (${months}/12) = ${money(I)}. Final amount = ${money(P+I)}.`};}},
{title:"Compound interest",make(){let c=pick(["A savings account","An education fund","An equipment replacement fund"]);let P=rnd(15,90)*100,r=pick([3,4,5,6,7]),years=rnd(2,8),n=pick([4,12,365]);let A=P*Math.pow(1+r/100/n,n*years);return {text:`${c} begins with ${money(P)} at ${r}% nominal annual interest, compounded ${n===4?"quarterly":n===12?"monthly":"daily"}, for ${years} years. Find the final balance.`,fields:["Final balance ($)"],answers:[A],tol:.025,hint:"Use A = P(1 + r/n)^(nt), with r written as a decimal.",solution:`A = ${money(P)}(1 + ${r/100}/${n})^(${n} × ${years}) = ${money(A)}.`};}},
{title:"Retirement contributions",make(){let salary=rnd(45,95)*1000,employee=pick([3,4,5,6]),match=pick([50,100]),years=rnd(4,12),rate=pick([3,4,5,6]);let weekly=salary*employee/100*(1+match/100)/52;let weeklyRate=rate/100/52;let fv=weekly*(Math.pow(1+weeklyRate,52*years)-1)/weeklyRate;return {text:`An employee earns ${money(salary)} per year, contributes ${employee}% of salary, and the employer matches ${match}% of that contribution. Assume the total is deposited in equal end-of-week amounts for ${years} years into an account earning ${rate}% annually, compounded weekly. Find the future value.`,fields:["Account balance ($)"],answers:[fv],tol:.10,hint:"Find the combined weekly contribution, then use the future value of an ordinary annuity with 52 periods per year.",solution:`Weekly deposit = ${money(weekly)}. FV = deposit × ((1+${rate/100}/52)^(${52*years})−1)/(${rate/100}/52) = ${money(fv)}.`};}},
{title:"Simple versus compound",make(){let P=rnd(15,60)*100,r=pick([3,4,5,6]),years=rnd(2,7),a=P*(1+r/100*years),b=P*Math.pow(1+r/100,years);return {text:`An investment of ${money(P)} earns ${r}% annually for ${years} years. Find the final balance under simple interest and annual compound interest.`,fields:["Simple balance ($)","Compound balance ($)"],answers:[a,b],hint:"Use P(1+rt) and P(1+r)^t.",solution:`Simple = ${money(a)}; compound = ${money(b)}.`};}},
{title:"Time to reach a goal",make(){let P=rnd(15,40)*100,target=P*pick([1.25,1.5,2]),r=pick([4,5,6,7]),t=Math.log(target/P)/(12*Math.log(1+r/1200));return {text:`A fund begins with ${money(P)} at ${r}% annual interest compounded monthly. How many years until it reaches ${money(target)}? Round to two decimals.`,fields:["Time (years)"],answers:[t],hint:"Use logarithms to solve A=P(1+r/12)^(12t).",solution:`t = ln(${target/P})/[12 ln(1+${r/1200})] = ${t.toFixed(2)} years.`};}}
],
loans:[
{title:"Simple-interest installment financing",make(){let c=pick(["A landscaping business purchases equipment","A furniture store offers installment financing","A repair shop finances tools"]);let P=rnd(8,30)*1000,r=pick([4.5,5,5.5,6,6.5,7]),years=rnd(2,5);let total=P*(1+r/100*years);return {text:`${c} with a ${money(P)} full simple-interest loan at ${r}% annually for ${years} years. Interest is calculated on the original principal. Find the total owed and equal monthly installment.`,fields:["Total owed ($)","Monthly installment ($)"],answers:[total,total/(12*years)],tol:.02,hint:"Use A = P(1+rt), then divide by the number of monthly installments.",solution:`Total = ${money(total)}. Monthly installment = ${money(total)} ÷ ${12*years} = ${money(total/(12*years))}.`};}},
{title:"Amortized loan payment",make(){let c=pick(["A small business borrows for renovations","A photographer finances new equipment","A family finances a used vehicle"]);let P=rnd(12,50)*1000,r=pick([4.8,5.4,6,6.6,7.2,8.4]),years=rnd(3,8),n=12*years,m=payment(P,r,n);return {text:`${c}. The principal is ${money(P)}, with ${r}% nominal annual interest and ${years} years of equal monthly payments. Find the monthly payment and total interest over the loan's life. Assume the displayed monthly payment is used for estimating total interest.`,fields:["Monthly payment ($)","Total interest ($)"],answers:[m,Math.round(m*100)/100*n-P],tol:.04,hint:"Monthly rate = annual rate ÷ 12. Use the amortized payment formula; for total interest multiply the rounded payment by the number of months and subtract principal.",solution:`Monthly payment = ${money(m)}. Estimated total interest = ${n} × ${money(m)} − ${money(P)} = ${money(Math.round(m*100)/100*n-P)}.`};}},
{title:"Credit-card repayment schedule",make(){let c=pick(["A credit card","A store financing card","A revolving credit account"]);let P=rnd(8,24)*100,r=pick([12,18,24,30]),pay=rnd(8,18)*10;let interest=P*r/1200,principal=pay-interest,balance=P-principal;return {text:`${c} has a starting balance of ${money(P)}, charges ${r}% nominal annual interest compounded monthly, and receives a ${money(pay)} payment at the end of the first month. Find the first month's interest, amount of payment applied to principal, and ending balance.`,fields:["Interest ($)","Principal repaid ($)","Ending balance ($)"],answers:[interest,principal,balance],tol:.02,hint:"Interest = opening balance × monthly rate. Principal repaid = payment − interest.",solution:`Interest = ${money(interest)}; principal repaid = ${money(principal)}; ending balance = ${money(balance)}.`};}},
{title:"Two rows of amortization",make(){let P=rnd(10,30)*1000,r=pick([4.8,6,7.2]),n=60,m=Math.round(payment(P,r,n)*100)/100,i1=Math.round(P*r/1200*100)/100,b1=Math.round((P-(m-i1))*100)/100,i2=Math.round(b1*r/1200*100)/100,b2=Math.round((b1-(m-i2))*100)/100;return {text:`A ${money(P)} loan at ${r}% nominal annual interest is repaid monthly over 5 years. Round each payment, interest amount and balance to cents. Find the monthly payment, month 1 interest, and balance after month 2.`,fields:["Monthly payment ($)","Month 1 interest ($)","Balance after month 2 ($)"],answers:[m,i1,b2],hint:"Interest = balance × monthly rate. New balance = old balance + interest − payment.",solution:`Payment = ${money(m)}; month 1 interest = ${money(i1)}, balance = ${money(b1)}; month 2 interest = ${money(i2)}, balance = ${money(b2)}.`};}},
{title:"Financing with down payment",make(){let price=rnd(15,45)*1000,d=pick([10,15,20]),P=price*(1-d/100),r=pick([4.8,6,7.2]),m=payment(P,r,48);return {text:`A studio buys equipment for ${money(price)} with ${d}% down and finances the rest for 4 years at ${r}% nominal annual interest with monthly payments. Find the down payment, amount financed and monthly payment.`,fields:["Down payment ($)","Amount financed ($)","Monthly payment ($)"],answers:[price-P,P,m],hint:"Subtract the down payment before computing the amortized monthly payment.",solution:`Down = ${money(price-P)}; financed = ${money(P)}; payment = ${money(m)}.`};}}
],
mortgage:[
{title:"Deferred student loan",make(){let c=pick(["A college student","A student in a professional training program","A graduate student"]);let P=rnd(12,35)*1000,r=pick([3.5,4,4.5,5,5.5]),months=pick([12,18,24,30]),repayRate=pick([4.8,5.4,6,6.6]),years=pick([8,10,12]);let interest=P*r/100*months/12,balance=P+interest,monthly=payment(balance,repayRate,years*12);return {text:`${c} borrows ${money(P)} at ${r}% annual simple interest. No payments are made for ${months} months. At repayment, the accrued interest is capitalized once, and the resulting balance is amortized over ${years} years at ${repayRate}% nominal annual interest with monthly payments. Find accrued interest, balance entering repayment, and monthly payment.`,fields:["Accrued interest ($)","Repayment balance ($)","Monthly payment ($)"],answers:[interest,balance,monthly],tol:.03,hint:"First compute simple interest using years. Add it to principal, then apply the amortized loan formula.",solution:`Accrued interest = ${money(interest)}; repayment balance = ${money(balance)}; monthly payment = ${money(monthly)}.`};}},
{title:"Mortgage and down payment",make(){let c=pick(["A family purchases a house","A buyer purchases a condominium","A couple purchases a townhouse"]);let price=rnd(18,48)*10000,down=pick([10,15,20,25]),r=pick([4.8,5.4,5.8,6,6.6]),years=pick([15,20,30]);let principal=price*(1-down/100),m=payment(principal,r,years*12),total=price*down/100+Math.round(m*100)/100*years*12;return {text:`${c} for ${money(price)}, makes a ${down}% down payment, and finances the rest with a ${years}-year mortgage at ${r}% nominal annual interest with monthly payments. Find the financed amount, monthly payment, and total paid including the down payment (excluding taxes, insurance, and fees).`,fields:["Amount financed ($)","Monthly payment ($)","Total paid ($)"],answers:[principal,m,total],tol:.05,hint:"Principal = purchase price − down payment. Apply the amortized payment formula; add down payment to all scheduled mortgage payments.",solution:`Financed = ${money(principal)}; payment = ${money(m)}; estimated total = ${money(total)}.`};}},
{title:"Interest paid during school",make(){let P=rnd(15,30)*1000,r=pick([4,5,6]),months=pick([12,18,24]),interest=P*r/100*months/12,repay=pick([5.4,6,6.6]),a=payment(P+interest,repay,120),b=payment(P,repay,120);return {text:`A student borrows ${money(P)} at ${r}% annual simple interest for ${months} months before repayment. Unpaid interest is capitalized once. The loan is then amortized over 10 years at ${repay}% nominal annual interest. Compare the monthly payment with no interest paid during school versus all school interest paid before repayment.`,fields:["Payment with capitalization ($)","Payment if interest was paid ($)"],answers:[a,b],hint:"Calculate simple interest first. The two repayment principals are P+I and P.",solution:`School interest = ${money(interest)}. Payments are ${money(a)} and ${money(b)}. Paying interest during school requires that separate earlier payment.`};}},
{title:"15-year versus 30-year mortgage",make(){let P=rnd(18,38)*10000,r=pick([4.8,5.4,6]),a=payment(P,r,180),b=payment(P,r,360),extra=(Math.round(b*100)/100)*360-(Math.round(a*100)/100)*180;return {text:`A buyer finances ${money(P)} at ${r}% nominal annual interest with monthly payments. Compare 15-year and 30-year mortgage payments and the extra total interest on the 30-year option. For total interest, use payments rounded to cents.`,fields:["15-year payment ($)","30-year payment ($)","Extra total interest ($)"],answers:[a,b,extra],hint:"Compute payments using 180 and 360 months. Compare total of payments.",solution:`15-year = ${money(a)}; 30-year = ${money(b)}; extra interest = ${money(extra)}.`};}}
]
};

// Convert unit names into consistent upright TeX labels.
const unitTeX={pounds:'lb',kilograms:'kg',ounces:'oz',miles:'mi',feet:'ft',kilometers:'km',meters:'m',gallons:'gal',quarts:'qt',yards:'yd',seconds:'s',hours:'h',inches:'in'};
function unitLabel(name){return `\\mathrm{${unitTeX[name]||name}}`;}
function texBlock(tex){return `<div class="math-method">\\[${tex}\\]</div>`;}
function unitCancellation(title,d){
 const t=d.text;
 if(title==='Weight conversion'){
  const match=t.match(/weighs ([\d.]+) (pounds|kilograms)\. Convert its weight to (kilograms|pounds|ounces)/);
  if(!match)return '';
  const [,quantity,from,to]=match;
  const f=from==='pounds'&&to==='kilograms'?'0.45359237':from==='kilograms'?'2.20462262':'16';
  return `<p>To make the original unit disappear, place it in the denominator of the conversion fraction. The matching units cancel, so the answer is expressed in ${to}.</p>`+texBlock(`${quantity}\\,\\cancel{${unitLabel(from)}}\\times\\frac{${f}\\,${unitLabel(to)}}{1\\,\\cancel{${unitLabel(from)}}}\\approx ${Number(d.answers[0].toFixed(2))}\\,${unitLabel(to)}`);
 }
 if(title==='Multi-step conversion'){
  const match=t.match(/measurement of ([\d.]+) (miles|kilometers|gallons)\. Express it in (feet|meters|quarts)/);
  if(!match)return '';
  const [,quantity,from,to]=match;const factor={miles:5280,kilometers:1000,gallons:4}[from];
  return `<p>Write the conversion factor with ${from} in the denominator and ${to} in the numerator. Cancel the original unit before multiplying.</p>`+texBlock(`${quantity}\\,\\cancel{${unitLabel(from)}}\\times\\frac{${factor}\\,${unitLabel(to)}}{1\\,\\cancel{${unitLabel(from)}}}=${Number(d.answers[0].toFixed(2))}\\,${unitLabel(to)}`);
 }
 if(title==='Speed conversion'){
  const match=t.match(/at ([\d.]+) miles per hour/);if(!match)return '';
  const mph=Number(match[1]);
  return `<p>Because the speed is in miles per hour, convert miles to feet and hours to seconds. Miles cancel between the original rate and the first fraction; hours cancel between the original rate and the second fraction.</p>`+texBlock(`\\frac{${mph}\\,\\cancel{\\mathrm{mi}}}{1\\,\\cancel{\\mathrm{h}}}\\times\\frac{5280\\,\\mathrm{ft}}{1\\,\\cancel{\\mathrm{mi}}}\\times\\frac{1\\,\\cancel{\\mathrm{h}}}{3600\\,\\mathrm{s}}\\approx ${d.answers[0].toFixed(2)}\\,\\frac{\\mathrm{ft}}{\\mathrm{s}}`);
 }
 if(title==='Area conversion'){
  const match=t.match(/covers ([\d.]+) square feet/);if(!match)return '';
  return `<p>Area units must be converted using the <em>square</em> of the length conversion. Since one yard is three feet, one square yard is nine square feet. The square-foot units cancel as follows.</p>`+texBlock(`${match[1]}\\,\\cancel{\\mathrm{ft}^2}\\times\\frac{1\\,\\mathrm{yd}^2}{9\\,\\cancel{\\mathrm{ft}^2}}=${d.answers[0]}\\,\\mathrm{yd}^2`);
 }
 if(title==='Unit rates'){
  const match=t.match(/pays \$([\d,.]+) for ([\d.]+) (pounds|yards|gallons)/);if(!match)return '';
  return `<p>A unit price is a ratio of dollars to the amount purchased. Dividing the total cost by the number of ${match[3]} gives the cost of one ${match[3].slice(0,-1)}.</p>`+texBlock(`\\frac{\\$${match[1]}}{${match[2]}\\,${unitLabel(match[3])}}\\approx \\$${d.answers[0].toFixed(2)}\\,/\\,${unitLabel(match[3])}`);
 }
 return '';
}
// Each explanation is generated from the same randomized problem instance as the answer checker.
function naturalSolution(title,d){
 if(d.authoredSolution)return d.authoredSolution;
 const t=d.text, a=d.answers, m=(n)=>money(n), f=(n,k=2)=>Number(n).toFixed(k), n=(n)=>num(n);
 const T=(s)=>`<div class="math-method">\\[${s}\\]</div>`;
 const P=(s)=>`<p>${s}</p>`;
 const get=(re)=>{let x=t.match(re);if(!x)throw Error('Unrecognized question: '+title);return x.slice(1)};
 const rate=(v)=>Number(v)/100;
 const fin=(i)=>`The requested ${d.fields[i].toLowerCase()} is <strong>${/\$/.test(d.fields[i])?m(a[i]):n(a[i])}${/\%/.test(d.fields[i])?'%':''}</strong>.`;
 let s='';
 switch(title){
 case 'Fahrenheit to Celsius': {let [F]=get(/(-?\d+)°F/);s=P(`The Fahrenheit and Celsius scales have different zero points, so we first subtract 32 from ${F}°F and then rescale by five ninths.`)+T(`C=\\frac59(${F}-32)=${f(a[0],1)}^\\circ\\mathrm C`)+P(`The temperature is approximately <strong>${f(a[0],1)}°C</strong>.`);break;}
 case 'Celsius to Fahrenheit': {let [C]=get(/(-?\d+)°C/);s=P(`Each Celsius degree corresponds to 9/5 Fahrenheit degrees, and the Fahrenheit scale begins 32 degrees higher. Applying both adjustments to ${C}°C gives`)+T(`F=\\frac95(${C})+32=${f(a[0],1)}^\\circ\\mathrm F`)+P(`Thus the converted reading is <strong>${f(a[0],1)}°F</strong>.`);break;}
 case 'Temperature changes and comparisons': {let [c1,c2]=get(/from (-?\d+)°C to (-?\d+)°C/);s=P(`We are converting a temperature <em>difference</em>, so there is no need to add 32. The change from ${c1}°C to ${c2}°C is ${Number(c2)-Number(c1)} Celsius degrees.`)+T(`\\Delta F=\\frac95\\bigl(${c2}-(${c1})\\bigr)=${f(a[0],1)}^\\circ\\mathrm F`)+P(`The temperature increased by <strong>${f(a[0],1)} Fahrenheit degrees</strong>.`);break;}
 case 'Weight conversion': {let [q,from,to]=get(/weighs ([\d.]+) (pounds|kilograms)\. Convert its weight to (kilograms|pounds|ounces)/);let factor=from==='pounds'&&to==='kilograms'?'0.45359237':from==='kilograms'?'2.2046226218':'16';s=P(`We want ${to}, so the conversion factor must have ${to} on top and ${from} on the bottom. Multiplying by this fraction changes the unit without changing the physical weight.`)+T(`${q}\\,\\cancel{${unitLabel(from)}}\\times\\frac{${factor}\\,${unitLabel(to)}}{1\\,\\cancel{${unitLabel(from)}}}\\approx ${f(a[0])}\\,${unitLabel(to)}`)+P(`The ${from} cancel, leaving <strong>${f(a[0])} ${to}</strong>.`);break;}
 case 'Multi-step conversion': {let [q,from,to]=get(/measurement of ([\d.]+) (miles|kilometers|gallons)\. Express it in (feet|meters|quarts)/);let factor={miles:5280,kilometers:1000,gallons:4}[from];s=P(`Since the measurement is given in ${from} but requested in ${to}, we use a conversion fraction with ${from} in its denominator. That way the original unit cancels and only ${to} remains.`)+T(`${q}\\,\\cancel{${unitLabel(from)}}\\times\\frac{${factor}\\,${unitLabel(to)}}{1\\,\\cancel{${unitLabel(from)}}}=${n(a[0])}\\,${unitLabel(to)}`)+P(`The converted measurement is <strong>${n(a[0])} ${to}</strong>.`);break;}
 case 'Unit rates': {let [price,q,u]=get(/pays \$([\d,.]+) for ([\d.]+) (pounds|yards|gallons)/);s=P(`A unit price tells us the cost for just one ${u.slice(0,-1)}. Dividing the total price by the number of ${u} puts dollars in the numerator and ${u} in the denominator.`)+T(`\\frac{\\$${price}}{${q}\\,${unitLabel(u)}}\\approx\\frac{\\$${f(a[0])}}{1\\,${unitLabel(u)}}`)+P(`The price is approximately <strong>${m(a[0])} per ${u.slice(0,-1)}</strong>.`);break;}
 case 'Speed conversion': {let [mph]=get(/at ([\d.]+) miles per hour/);s=P(`We need feet in place of miles and seconds in place of hours. Multiplying by 5,280 feet per mile and by one hour per 3,600 seconds makes both original units cancel.`)+T(`\\frac{${mph}\\,\\cancel{\\mathrm{mi}}}{\\cancel{\\mathrm h}}\\times\\frac{5280\\,\\mathrm{ft}}{\\cancel{\\mathrm{mi}}}\\times\\frac{\\cancel{\\mathrm h}}{3600\\,\\mathrm s}\\approx${f(a[0])}\\,\\frac{\\mathrm{ft}}{\\mathrm s}`)+P(`The vehicle is traveling at approximately <strong>${f(a[0])} feet per second</strong>.`);break;}
 case 'Area conversion': {let [sq]=get(/covers ([\d.]+) square feet/);s=P(`Because this is an <em>area</em>, we must square the length conversion: one yard equals three feet, so one square yard equals nine square feet. The square-foot units cancel in the fraction below.`)+T(`${sq}\\,\\cancel{\\mathrm{ft}^2}\\times\\frac{1\\,\\mathrm{yd}^2}{9\\,\\cancel{\\mathrm{ft}^2}}=${n(a[0])}\\,\\mathrm{yd}^2`)+P(`The garden covers <strong>${n(a[0])} square yards</strong>.`);break;}
 case 'Discount and sales tax': {let [price,discount,tax]=get(/priced at \$([\d,.]+)\. It is discounted by (\d+)%, then (\d+)% sales tax/);let p=Number(price.replaceAll(',',''));let after=p*(1-rate(discount));s=P(`The discount is applied before sales tax. A ${discount}% discount leaves ${100-discount}% of the listed price, or ${m(after)}. Sales tax is then calculated on that reduced price.`)+T(`\\$${p}\\left(1-\\frac{${discount}}{100}\\right)\\left(1+\\frac{${tax}}{100}\\right)=\\$${f(a[0])}`)+P(`The customer pays <strong>${m(a[0])}</strong> after both adjustments.`);break;}
 case 'Successive percentage increases': {let [price,r1,r2]=get(/starting cost is \$([\d,.]+)\. The cost increases (\d+)%, then increases another (\d+)%/);s=P(`The second increase is applied to a cost that has already increased, not to the original cost. We therefore multiply the original amount by both growth factors.`)+T(`\\$${price.replaceAll(',','')}\\left(1+\\frac{${r1}}{100}\\right)\\left(1+\\frac{${r2}}{100}\\right)\\approx\\$${f(a[0])}`)+P(`To express the overall change as a percentage, we compare the final cost with the starting cost.`)+T(`\\frac{${f(a[0],4)}-${price.replaceAll(',','')}}{${price.replaceAll(',','')}}\\times100\\%\\approx${f(a[1])}\\%`)+P(`The final cost is <strong>${m(a[0])}</strong>, an overall increase of <strong>${f(a[1])}%</strong>.`);break;}
 case 'Reverse percentages': {let [pct,sale]=get(/After a (\d+)% discount, .* costs \$([\d,.]+)\./);s=P(`After a ${pct}% discount, the sale price represents ${100-pct}% of the original price. Dividing by that remaining proportion reverses the discount.`)+T(`\\text{Original price}=\\frac{\\$${sale.replaceAll(',','')}}{1-${pct}/100}=\\$${f(a[0])}`)+P(`The item originally cost <strong>${m(a[0])}</strong>.`);break;}
 case 'Percent change': {let [old,now]=get(/changes from (\d+) to ([\d,.]+) visitors/);s=P(`Percentage change measures the difference relative to the <em>original</em> attendance. We subtract the original count from the new count, then divide by the original count.`)+T(`\\frac{${now.replaceAll(',','')}-${old}}{${old}}\\times100\\%=${f(a[0])}\\%`)+P(`The ${a[0]<0?'negative sign indicates a decrease':'positive sign indicates an increase'} of <strong>${Math.abs(a[0])}%</strong>.`);break;}
 case 'Markup versus profit margin': {let [cost,pct]=get(/for \$([\d,.]+) and marks it up (\d+)%/);let p=Number(cost.replaceAll(',',''));s=P(`A ${pct}% markup is based on the purchase cost, so we first multiply that cost by ${1+rate(pct)} to find the selling price. Profit margin is different: it compares the profit with the <em>selling price</em>, not the cost.`)+T(`\\text{Selling price}=\\$${p}\\left(1+\\frac{${pct}}{100}\\right)=\\$${f(a[0])}`)+T(`\\text{Margin}=\\frac{${f(a[0])}-${p}}{${f(a[0])}}\\times100\\%\\approx${f(a[1])}\\%`)+P(`The selling price is <strong>${m(a[0])}</strong> and the profit margin is <strong>${f(a[1])}%</strong>.`);break;}
 case 'Monthly budget categories': {let [income,housing,transport,food,other]=get(/earns \$([\d,.]+) monthly\. Housing: \$([\d,.]+); transportation: \$([\d,.]+); food: \$([\d,.]+); other expenses: \$([\d,.]+)/);let vals=[housing,transport,food,other].map(v=>parseFloat(v.replaceAll(',',''))),total=vals.reduce((x,y)=>x+y,0);s=P(`The household's savings are what remains after paying all four expense categories. Adding the expenses gives ${m(total)}, which we subtract from the monthly income.`)+T(`\\text{Savings}=\\$${income.replaceAll(',','')}-\\$${total}=\\$${f(a[0])}`)+P(`For the housing percentage, we compare housing expenses with the full monthly income, rather than with total spending.`)+T(`\\frac{${vals[0]}}{${income.replaceAll(',','')}}\\times100\\%\\approx${f(a[1])}\\%`)+P(`Monthly savings are <strong>${m(a[0])}</strong>, and housing accounts for <strong>${f(a[1])}%</strong> of income.`);break;}
 case 'Build a pie chart': {let v=d.pieParts;s=P(`A pie chart represents the entire budget as a circle, so its sectors must total 100%. Each target percentage gives that category's share of the circle.`)+T(v.map((x,i)=>`${x}\\%`).join('+')+'=100\\%')+P(`Set the sliders to Housing ${v[0]}%, Transport ${v[1]}%, Food ${v[2]}%, and Other ${v[3]}%. The remaining <strong>${v[4]}%</strong> belongs to Savings. The corresponding central angles are ${v.map(x=>f(3.6*x,1)+'°').join(', ')} in that same order.`);break;}
 case 'Budget surplus or deficit': {let [income]=get(/earns \$([\d,.]+) each month/);let values=[...t.matchAll(/\$([\d,.]+)/g)].map(x=>Number(x[1].replaceAll(',',''))),total=values.slice(1).reduce((x,y)=>x+y,0);s=P(`The three expenses add up to ${m(total)}. Subtracting that amount from the income tells us whether there is money left over or a shortfall.`)+T(`\\text{Surplus}=\\$${income.replaceAll(',','')}-\\$${total}=\\$${f(a[0])}`)+P(`To measure how much of the income is spent, divide total expenses by income.`)+T(`\\frac{${total}}{${income.replaceAll(',','')}}\\times100\\%\\approx${f(a[1])}\\%`)+P(`This is a <strong>${a[0]<0?'deficit':'surplus'} of ${m(Math.abs(a[0]))}</strong>; expenses account for <strong>${f(a[1])}%</strong> of income.`);break;}
 case 'Monthly savings target': {let [goal,saved,months]=get(/save \$([\d,.]+) for a computer and already has \$([\d,.]+)\. With no interest, how much must be saved per month for the next (\d+) months/);let needed=Number(goal.replaceAll(',',''))-Number(saved.replaceAll(',',''));s=P(`The student already has part of the savings goal, so only ${m(needed)} remains to be saved. With no interest, that remaining amount is divided equally over ${months} months.`)+T(`\\frac{\\$${goal.replaceAll(',','')}-\\$${saved.replaceAll(',','')}}{${months}\\,\\text{months}}\\approx\\$${f(a[0])}\\,/\\text{month}`)+P(`Saving approximately <strong>${m(a[0])} each month</strong> will reach the goal.`);break;}
 case 'Simple-interest investment': {let [principal,r,months]=get(/starts with \$([\d,.]+) and earns ([\d.]+)% annual simple interest for (\d+) months/);s=P(`Simple interest is calculated only on the original investment. Since the rate is annual, we express ${months} months as ${months}/12 years before using the simple-interest formula.`)+T(`I=${principal.replaceAll(',','')}\\left(\\frac{${r}}{100}\\right)\\left(\\frac{${months}}{12}\\right)=\\$${f(a[0])}`)+P(`The investment earns ${m(a[0])} in interest. Adding this to the original principal gives a final amount of <strong>${m(a[1])}</strong>.`);break;}
 case 'Compound interest': {let [principal,r,frequency,years]=get(/begins with \$([\d,.]+) at ([\d.]+)% nominal annual interest, compounded (quarterly|monthly|daily), for (\d+) years/);let periods={quarterly:4,monthly:12,daily:365}[frequency];s=P(`With ${frequency} compounding, interest is added to the balance ${periods} times each year. The periodic rate is ${r}% divided by ${periods}, and the number of periods is ${periods} times ${years}.`)+T(`A=${principal.replaceAll(',','')}\\left(1+\\frac{${r}/100}{${periods}}\\right)^{${periods}\\cdot${years}}\\approx\\$${f(a[0])}`)+P(`After ${years} years, the account contains approximately <strong>${m(a[0])}</strong>.`);break;}
 case 'Retirement contributions': {let [salary,employee,match,years,r]=get(/earns \$([\d,.]+) per year, contributes (\d+)% of salary, and the employer matches (\d+)% of that contribution.*for (\d+) years.*earning (\d+)% annually/);let annual=Number(salary.replaceAll(',',''))*rate(employee)*(1+rate(match)),weekly=annual/52; s=P(`The employee contributes ${employee}% of the annual salary, and the employer adds ${match}% of the employee's contribution. Together they deposit ${m(annual)} per year, or approximately ${m(weekly)} at the end of each week.`)+P(`Because deposits occur repeatedly at the <em>end</em> of each period, we use the future value of an ordinary annuity with ${52*Number(years)} weekly deposits.`)+T(`FV=\\frac{${f(weekly,6)}\\left[\\left(1+\\frac{${r}/100}{52}\\right)^{${52*Number(years)}}-1\\right]}{${r}/(100\\cdot52)}\\approx\\$${f(a[0])}`)+P(`The retirement account is worth approximately <strong>${m(a[0])}</strong> after ${years} years.`);break;}
 case 'Simple versus compound': {let [principal,r,years]=get(/investment of \$([\d,.]+) earns (\d+)% annually for (\d+) years/);s=P(`Under simple interest, each year's interest is based on the original principal. With annual compounding, each year's interest is added to the balance, so later interest is earned on previous interest.`)+T(`A_{\\mathrm{simple}}=${principal.replaceAll(',','')}\\left(1+\\frac{${r}}{100}\\cdot${years}\\right)=\\$${f(a[0])}`)+T(`A_{\\mathrm{compound}}=${principal.replaceAll(',','')}\\left(1+\\frac{${r}}{100}\\right)^{${years}}\\approx\\$${f(a[1])}`)+P(`The simple-interest balance is <strong>${m(a[0])}</strong>, while the compounded balance is <strong>${m(a[1])}</strong>.`);break;}
 case 'Time to reach a goal': {let [principal,r,target]=get(/begins with \$([\d,.]+) at (\d+)% annual interest compounded monthly\. How many years until it reaches \$([\d,.]+)/);s=P(`Time appears in the exponent of the compound-interest equation. Dividing by the starting balance and taking natural logarithms allows us to isolate the number of years.`)+T(`\\frac{${target.replaceAll(',','')}}{${principal.replaceAll(',','')}}=\\left(1+\\frac{${r}/100}{12}\\right)^{12t}`)+T(`t=\\frac{\\ln(${target.replaceAll(',','')}/${principal.replaceAll(',','')})}{12\\ln(1+${r}/1200)}\\approx${f(a[0])}\\,\\text{years}`)+P(`The goal is reached after approximately <strong>${f(a[0])} years</strong>.`);break;}
 case 'Simple-interest installment financing': {let [principal,r,years]=get(/with a \$([\d,.]+) full simple-interest loan at ([\d.]+)% annually for (\d+) years/);s=P(`This financing plan charges simple interest on the original principal for the entire ${years}-year term. After adding that interest to the amount borrowed, we spread the total equally over ${12*Number(years)} monthly installments.`)+T(`A=${principal.replaceAll(',','')}\\left(1+\\frac{${r}}{100}\\cdot${years}\\right)=\\$${f(a[0])}`)+T(`M=\\frac{\\$${f(a[0])}}{${12*Number(years)}\\,\\text{months}}\\approx\\$${f(a[1])}\\,/\\text{month}`)+P(`The borrower owes <strong>${m(a[0])}</strong> in total, paid in installments of approximately <strong>${m(a[1])}</strong>.`);break;}
 case 'Amortized loan payment': {let [principal,r,years]=get(/principal is \$([\d,.]+), with ([\d.]+)% nominal annual interest and (\d+) years/);let N=12*Number(years);s=P(`An amortized loan charges interest on the balance still owed each month. With an annual rate of ${r}%, the monthly rate is ${r}/1200, and ${years} years gives ${N} payments.`)+T(`M=\\frac{${principal.replaceAll(',','')}(${r}/1200)}{1-(1+${r}/1200)^{-${N}}}\\approx\\$${f(a[0])}`)+P(`The monthly payment is approximately ${m(a[0])}. To estimate total interest, multiply the payment <em>rounded to cents</em> by ${N} and subtract the original principal.`)+T(`I\\approx${N}(${f(a[0])})-${principal.replaceAll(',','')}=\\$${f(a[1])}`)+P(`The estimated total interest is <strong>${m(a[1])}</strong>.`);break;}
 case 'Credit-card repayment schedule': {let [principal,r,pay]=get(/starting balance of \$([\d,.]+), charges (\d+)% nominal annual interest compounded monthly, and receives a \$([\d,.]+) payment/);s=P(`The card charges one month's interest on the opening balance. Only the part of the ${m(Number(pay.replaceAll(',','')))} payment that remains after interest reduces the principal.`)+T(`\\text{Interest}=${principal.replaceAll(',','')}\\left(\\frac{${r}}{1200}\\right)=\\$${f(a[0])}`)+T(`\\text{Principal repaid}=${pay.replaceAll(',','')}-${f(a[0])}=\\$${f(a[1])}`)+P(`Subtracting the principal repaid from the original balance leaves <strong>${m(a[2])}</strong> owed at the end of the month.`);break;}
 case 'Two rows of amortization': {let [principal,r]=get(/A \$([\d,.]+) loan at ([\d.]+)% nominal annual interest/);let p=Number(principal.replaceAll(',','')),monthly=Number(f(a[0])),i1=Number(f(a[1])),b1=Number((p+i1-monthly).toFixed(2)),i2=Number((b1*Number(r)/1200).toFixed(2));s=P(`We first calculate the fixed monthly payment for a five-year amortized loan. Each month, interest is calculated on the opening balance, and the remainder of the payment reduces principal.`)+T(`M=\\frac{${p}(${r}/1200)}{1-(1+${r}/1200)^{-60}}\\approx\\$${f(a[0])}`)+P(`In month 1, interest is ${m(i1)}, so the new balance is ${m(b1)} after the payment. The second month's interest is then based on this smaller balance.`)+T(`B_2=${f(b1)}+${f(i2)}-${f(a[0])}=\\$${f(a[2])}`)+P(`The balance after two payments is <strong>${m(a[2])}</strong>.`);break;}
 case 'Financing with down payment': {let [price,down,r]=get(/equipment for \$([\d,.]+) with (\d+)% down and finances the rest for 4 years at ([\d.]+)%/);s=P(`The down payment is paid immediately and is not part of the loan. We calculate it as ${down}% of the purchase price, then subtract it to find the financed principal.`)+T(`\\text{Down payment}=${price.replaceAll(',','')}\\left(\\frac{${down}}{100}\\right)=\\$${f(a[0])}`)+T(`P=${price.replaceAll(',','')}-${f(a[0])}=\\$${f(a[1])}`)+P(`The remaining ${m(a[1])} is amortized over 48 monthly payments at ${r}% annual interest.`)+T(`M=\\frac{${f(a[1])}(${r}/1200)}{1-(1+${r}/1200)^{-48}}\\approx\\$${f(a[2])}`)+P(`The monthly payment is approximately <strong>${m(a[2])}</strong>.`);break;}
 case 'Deferred student loan': {let [principal,r,months,years,repay]=get(/borrows \$([\d,.]+) at ([\d.]+)% annual simple interest\. No payments are made for (\d+) months.*over (\d+) years at ([\d.]+)%/);s=P(`During the ${months}-month period without payments, interest accumulates on the original loan at the simple annual rate of ${r}%. We convert the months to years before finding that interest.`)+T(`I=${principal.replaceAll(',','')}\\left(\\frac{${r}}{100}\\right)\\left(\\frac{${months}}{12}\\right)=\\$${f(a[0])}`)+P(`Because the unpaid interest is capitalized when repayment begins, it is added to the original principal, producing a new balance of ${m(a[1])}. That balance is then amortized over ${12*Number(years)} monthly payments at ${repay}% annual interest.`)+T(`M=\\frac{${f(a[1])}(${repay}/1200)}{1-(1+${repay}/1200)^{-${12*Number(years)}}}\\approx\\$${f(a[2])}`)+P(`The monthly payment is approximately <strong>${m(a[2])}</strong>.`);break;}
 case 'Mortgage and down payment': {let [price,down,years,r]=get(/for \$([\d,.]+), makes a (\d+)% down payment, and finances the rest with a (\d+)-year mortgage at ([\d.]+)%/);let dp=Number(price.replaceAll(',',''))-a[0],N=12*Number(years);s=P(`The buyer pays ${down}% of the purchase price up front, leaving ${m(a[0])} to finance. The mortgage payment is calculated using the monthly interest rate and ${N} monthly installments.`)+T(`P=${price.replaceAll(',','')}\\left(1-\\frac{${down}}{100}\\right)=\\$${f(a[0])}`)+T(`M=\\frac{${f(a[0])}(${r}/1200)}{1-(1+${r}/1200)^{-${N}}}\\approx\\$${f(a[1])}`)+P(`To estimate the total paid for the house, we add the ${m(dp)} down payment to all ${N} monthly payments, using the monthly payment rounded to cents.`)+T(`\\text{Total}=${f(dp)}+${N}(${f(a[1])})=\\$${f(a[2])}`)+P(`The estimated total is <strong>${m(a[2])}</strong>, excluding taxes, insurance, and fees.`);break;}
 case 'Interest paid during school': {let [principal,r,months,repay]=get(/borrows \$([\d,.]+) at (\d+)% annual simple interest for (\d+) months before repayment.*over 10 years at ([\d.]+)%/);let p=Number(principal.replaceAll(',','')),I=p*Number(r)/100*Number(months)/12;s=P(`During school, the loan accumulates ${m(I)} of simple interest. If this interest is unpaid, it is added to the principal at repayment, increasing the balance from ${m(p)} to ${m(p+I)}.`)+T(`I=${p}\\left(\\frac{${r}}{100}\\right)\\left(\\frac{${months}}{12}\\right)=\\$${f(I)}`)+P(`Using the same ten-year amortization formula and ${repay}% annual repayment rate for both cases gives ${m(a[0])} per month with capitalization and ${m(a[1])} per month when the accrued interest was paid earlier.`)+P(`Paying the school interest separately therefore reduces the later monthly payment by <strong>${m(a[0]-a[1])}</strong>, although it requires an earlier payment of ${m(I)}.`);break;}
 case '15-year versus 30-year mortgage': {let [principal,r]=get(/finances \$([\d,.]+) at ([\d.]+)% nominal annual interest/);s=P(`Both mortgages use the same principal and annual interest rate, but the 15-year loan has 180 payments while the 30-year loan has 360. Spreading repayment over more months lowers each payment, though interest accumulates for longer.`)+T(`M_{15}=\\frac{${principal.replaceAll(',','')}(${r}/1200)}{1-(1+${r}/1200)^{-180}}\\approx\\$${f(a[0])}`)+T(`M_{30}=\\frac{${principal.replaceAll(',','')}(${r}/1200)}{1-(1+${r}/1200)^{-360}}\\approx\\$${f(a[1])}`)+P(`Using payments rounded to cents, the difference between the total amounts paid is`)+T(`360(${f(a[1])})-180(${f(a[0])})=\\$${f(a[2])}`)+P(`The 30-year mortgage costs approximately <strong>${m(a[2])} more in total interest</strong>, despite its smaller monthly payment.`);break;}
 default: throw Error('No authored explanation for '+title);
 }
 return s;
}

let current=null,instances=[];
function renderTopics(){ $("#topics").innerHTML=topics.map(([id,name,desc])=>`<button class="topic ${id===current?"active":""}" data-topic="${id}" aria-pressed="${id===current}">${name}<span>${desc}</span></button>`).join("");document.querySelectorAll("[data-topic]").forEach(b=>b.onclick=()=>selectTopic(b.dataset.topic));}
function selectTopic(id){current=id;instances=questions[id].map(q=>({q,data:q.make()}));renderTopics();$("#intro").hidden=true;$("#questions").innerHTML=`<h2>${topics.find(t=>t[0]===id)[1]}</h2><p class="muted">Round final numerical answers to two decimal places (including dollars and percentages), unless a question states otherwise. Keep full precision in intermediate calculations. Use New Version for another problem.</p>`+instances.map((_,i)=>`<article class="card" id="card-${i}"></article>`).join("");instances.forEach((_,i)=>renderCard(i));}
function renderCard(i){let {q,data}=instances[i],el=document.getElementById(`card-${i}`);el.innerHTML=`<h3>${i+1}. ${q.title}</h3><div class="prompt">${data.text}</div>${q.pie?`<div class="pie" id="pie-${i}" role="img" aria-label="Pie chart preview"></div><div id="pie-controls-${i}"></div><div class="key" id="key-${i}"></div>`:`<div class="answers">${data.fields.map((f,j)=>`<label>${f}<input type="number" step="any" inputmode="decimal" id="answer-${i}-${j}" placeholder="Your answer"></label>`).join("")}</div>`}<div class="actions"><button class="primary" data-action="check">Check Answer</button><button data-action="hint">Hint</button><button data-action="solution">Show Solution</button><button data-action="new">New Version</button></div><div id="feedback-${i}" aria-live="polite"></div><div id="details-${i}"></div>`;el.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>act(i,b.dataset.action));if(q.pie)renderPie(i);typesetMath(el);}
function renderPie(i){let d=instances[i].data,vals=instances[i].pieVals||[20,20,20,20,20],names=["Housing","Transport","Food","Other","Savings"],colors=["#2e6aa6","#e1a23c","#35a17b","#8a6ab8","#d76d6d"];if(!instances[i].pieVals)instances[i].pieVals=vals;let start=0,stops=vals.map((v,j)=>{let old=start;start+=v;return `${colors[j]} ${old}% ${start}%`});document.getElementById(`pie-${i}`).style.background=`conic-gradient(${stops.join(",")})`;document.getElementById(`pie-controls-${i}`).innerHTML=names.slice(0,4).map((n,j)=>`<div class="pie-control"><label>${n}: <strong>${vals[j]}%</strong><input type="range" min="0" max="${100-vals.slice(0,4).reduce((a,b,k)=>a+(k===j?0:b),0)}" value="${vals[j]}" data-pie="${j}"></label></div>`).join("")+`<p><strong>Savings:</strong> ${vals[4]}% (remaining)</p>`;document.getElementById(`key-${i}`).innerHTML=names.map((n,j)=>`<span><i class="swatch" style="background:${colors[j]}"></i>${n}</span>`).join("");document.querySelectorAll(`#pie-controls-${i} [data-pie]`).forEach(s=>s.oninput=()=>{let j=+s.dataset.pie;vals[j]=+s.value;vals[4]=100-vals.slice(0,4).reduce((a,b)=>a+b,0);renderPie(i);});}
function act(i,action){let item=instances[i],d=item.data,f=document.getElementById(`feedback-${i}`),details=document.getElementById(`details-${i}`);if(action==="new"){item.data=item.q.make();delete item.pieVals;renderCard(i);return;}if(action==="hint"){details.innerHTML=`<div class="details"><strong>Hint:</strong> ${d.hint}</div>`;typesetMath(details);return;}if(action==="solution"){
 const explanation=naturalSolution(item.q.title,d);
 details.innerHTML=`<div class="details solution-prose"><strong>Worked explanation</strong>${explanation}</div>`;
 typesetMath(details);return;
}if(action==="check"){let correct=false,partial=0;if(item.q.pie){let vals=item.pieVals;partial=vals.filter((v,j)=>v===d.pieParts[j]).length;correct=partial===5;}else{let inputs=d.answers.map((_,j)=>document.getElementById(`answer-${i}-${j}`).value);if(inputs.some(x=>x.trim()==="")){f.className="feedback bad";f.textContent="Please complete every answer field before checking.";return;}partial=inputs.filter((x,j)=>close(Number(x),d.answers[j], d.decimals?.[j] ?? (/number of/i.test(d.fields[j])?0:2))).length;correct=partial===d.answers.length;}f.className=`feedback ${correct?"good":"bad"}`;f.textContent=correct?"Correct! Great work.":`Not yet: ${partial} of ${item.q.pie?5:d.answers.length} parts correct. Try again or open the hint.`;if(!item.q.pie){d.answers.forEach((expected,j)=>{const v=document.getElementById(`answer-${i}-${j}`).value;const ok=v.trim()!==""&&close(Number(v),expected,d.decimals?.[j]??(/number of/i.test(d.fields[j])?0:2));const field=document.getElementById(`answer-${i}-${j}`);field.setAttribute("aria-invalid",String(!ok));field.parentElement.style.color=ok?"#126038":"#9b3c25";});}}}
renderTopics();
